import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import Navbar from "./components/Navbar";
import Home from "./pages/Home";
import About from "./pages/About";
import FAQ from "./pages/FAQ";
import Contact from "./pages/Contact";
import Login from "./pages/Login";
import Register from "./pages/Register";
import AddCurso from "./pages/aluno/AddCurso";
import DetailCurso from "./pages/aluno/DetailCurso";
import ListaCurso from "./pages/aluno/ListaCurso";
import Aula from "./pages/aluno/Aula";
import Avaliacao from "./pages/aluno/avaliacao";
import LecionaLista from "./pages/professor/lecionalista";
import LecionaAula from "./pages/professor/lecionaaula";
import LecionaAvaliacao from "./pages/professor/lecionaavaliacao";
import AdmListCurso from "./pages/administrador/admlistcurso";
import AdmAddCurso from "./pages/administrador/admaddcurso";
import AdminfCurso from "./pages/administrador/adminfcurso";
import AdmListProf from "./pages/administrador/admlistprof";
import AdmAddProf from "./pages/administrador/admaddprof";
im

function App() {
  return (
    <Router>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="/faq" element={<FAQ />} />
        <Route path="/addcurso" element={<AddCurso />} />
        <Route path="/detailcurso" element={<DetailCurso />} />
        <Route path="/aula" element={<Aula />} />
        <Route path="/avaliacao" element={<Avaliacao />} />
        <Route path="/listacurso" element={<ListaCurso />} />
        <Route path="/lecionalista" element={<LecionaLista />} />
        <Route path="/lecionaaula" element={<LecionaAula />} />
        <Route path="/lecionaavaliacao" element={<LecionaAvaliacao />} />
        <Route path="/admlistcurso" element={<AdmListCurso />} />
        <Route path="/admaddcurso" element={<AdmAddCurso />} />
        <Route path="/adminfcurso" element={<AdminfCurso />} />
        <Route path="/admlistprof" element={<AdmListProf />} />
        <Route path="/admaddprof" element={<AdmAddProf />} />
        <Route path="/contact" element={<Contact />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
      </Routes>
    </Router>
  );
}

export default App;
